{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6fbf8;--card:#fff;--muted:#64707a;--accent:#2b7a63;--accent-2:#1f5b45}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#123;line-height:1.45;background:var(--bg);}
    header{background:linear-gradient(180deg,rgba(43,122,99,0.06),transparent);padding:28px 20px;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav{display:flex;gap:18px;align-items:center;max-width:1100px;margin:0 auto}
    nav a{color:var(--accent-2);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:start}
    .card{background:var(--card);padding:22px;border-radius:12px;box-shadow:0 6px 18px rgba(16,24,32,0.06)}
    h1{margin:0 0 8px;font-size:22px;color:#0f2b24}
    p.lead{color:var(--muted);margin:0 0 14px}
    .meta{font-size:13px;color:var(--muted);display:flex;gap:12px;flex-wrap:wrap}
    .approach{margin-top:22px;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
    .approach .item{padding:14px;border-radius:10px;background:linear-gradient(180deg,#fff,rgba(250,252,250,0.6));border:1px solid rgba(16,24,32,0.03)}
    .framework{display:flex;gap:18px;margin-top:24px}
    .framework .left{flex:1}
    .cta{margin-top:22px}
    .btn{display:inline-block;background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    .btn.secondary{background:transparent;color:var(--accent-2);border:1px solid rgba(31,91,69,0.12)}
    footer{max-width:1100px;margin:42px auto;padding:20px;border-top:1px solid rgba(0,0,0,0.04);color:var(--muted)}
    /* Pattern background using SVG file reference (assets/img/pattern.svg) */
    .pattern{position:absolute;right:12px;top:100px;opacity:0.06;width:260px;height:260px;pointer-events:none;background-image:url('assets/img/pattern.svg');background-size:contain;background-repeat:no-repeat}
    /* Modal and components */
    .modal{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:rgba(7,15,12,0.42);z-index:80}
    .modal.open{display:flex}
    .modal .panel{width:720px;max-width:94%;background:#fff;padding:20px;border-radius:12px;box-shadow:0 20px 60px rgba(10,20,18,0.24)}
    .modal .close{float:right;background:transparent;border:0;font-size:18px}
    .exercise-area{display:grid;grid-template-columns:1fr 240px;gap:16px;align-items:start}
    .breath-circle{width:160px;height:160px;border-radius:50%;background:linear-gradient(180deg,#e9f7f1,#d7efe6);display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent-2);margin:0 auto}
    .footnote{font-size:12px;color:var(--muted);margin-top:12px}
    /* Habit builder compact */
    .habit-compact{margin-top:18px;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,rgba(236,250,244,0.6));border:1px solid rgba(31,91,69,0.06)}
    .habit-compact input[type=text]{width:100%;padding:8px;border:1px solid rgba(16,24,32,0.06);border-radius:8px}
    .habit-compact button{margin-top:10px}
    @media(max-width:900px){.hero{grid-template-columns:1fr}.framework{flex-direction:column}.exercise-area{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <nav class="wrap">
      <a href="index.html">Start</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <div class="wrap">
    <div class="hero">
      <div class="card">
        <h1>Clear structure for steady daily practice</h1>
        <p class="lead">We design small, repeatable actions that accumulate into measurable improvement. No gimmicks—just an evidence-minded approach to consistent self-care.</p>
        <div class="meta">
          <div>Membership model: ongoing support</div>
          <div>Primary support: habit architecture & micro-practices</div>
        </div>

        <div class="framework">
          <div class="left">
            <h3>Our steady method</h3>
            <p class="footnote">A three-part loop: Identify a manageable action, anchor it to an existing routine, and review quickly each week. The loop keeps momentum without heavy planning.</p>
            <div class="approach" aria-hidden>
              <div class="item"><strong>Pinpoint</strong><div style="margin-top:8px;color:var(--muted)">Choose one behavior that matters this week.</div></div>
              <div class="item"><strong>Anchor</strong><div style="margin-top:8px;color:var(--muted)">Connect it to something you already do daily.</div></div>
              <div class="item"><strong>Check</strong><div style="margin-top:8px;color:var(--muted)">A short weekly review to notice what’s working.</div></div>
            </div>
          </div>
          <div>
            <div style="display:flex;flex-direction:column;gap:12px">
              <a class="btn" href="#" id="openExercise">Try a guided exercise</a>
              <a class="btn secondary" href="programs.html">See program formats</a>
            </div>
            <div class="habit-compact">
              <label style="font-weight:700;display:block;margin-bottom:6px">Build a 7-day check: lightweight</label>
              <input id="habitInput" type="text" placeholder="e.g., Morning hydration, 2 min journaling">
              <button class="btn" id="makeChallenge">Create my week checklist</button>
            </div>
          </div>
        </div>
      </div>

      <div style="height:100%">
        <div class="card">
          <h3>About the coach</h3>
          <p style="color:var(--muted)">Clinical curiosity meets pragmatic structure. Sessions focus on stable habits, measurable progress, and repeatable practices that fit busy schedules.</p>
          <div style="margin-top:12px">
            <a class="btn" href="book.html">Book a short consult</a>
            <div style="margin-top:8px;color:var(--muted);font-size:13px">Call: {{PHONE}} • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
          </div>
        </div>
        <div class="pattern" aria-hidden></div>
      </div>
    </div>

    <section style="margin-top:22px" class="card">
      <h2 style="margin-top:0">How we track progress</h2>
      <p class="footnote">A short, weekly log that focuses on frequency and perceived effort. We avoid overcomplication: two numbers give enough insight to adapt.</p>
      <ol style="color:var(--muted)">
        <li>Record whether the action occurred each day.</li>
        <li>Note effort (1–5) and any contextual notes.</li>
        <li>Review on day seven to adjust anchors.</li>
      </ol>
    </section>

    <section style="margin-top:18px;display:flex;gap:14px">
      <a class="btn" href="services.html">Explore Offerings</a>
      <a class="btn secondary" href="programs.html">Compare course formats</a>
    </section>
  </div>

  <footer>
    <div class="wrap">Serving {{CITY}}, {{STATE}} • Confidential, structured support for daily wellbeing.</div>
  </footer>

  <!-- Modal: Guided exercise -->
  <div id="exerciseModal" class="modal" aria-hidden="true">
    <div class="panel" role="dialog" aria-modal="true" aria-labelledby="exerciseTitle">
      <button class="close" id="closeExercise">✕</button>
      <h3 id="exerciseTitle">Guided practice</h3>
      <div style="font-size:13px;color:var(--muted);margin-bottom:10px">Select a short routine and follow the timer. Use this to restore focus or ground the start of a day.</div>
      <div class="exercise-area">
        <div>
          <label style="display:block;margin-bottom:8px;font-weight:700">Choose exercise</label>
          <select id="exerciseSelect" style="width:100%;padding:8px;border-radius:8px;border:1px solid rgba(16,24,32,0.06)">
            <option value="breathing">Breathing reset — 3 minutes</option>
            <option value="journaling">2-minute focused journal prompt</option>
            <option value="intention">Set an intention — structured steps</option>
          </select>

          <div id="exerciseContent" style="margin-top:12px"></div>
        </div>
        <div>
          <div style="padding:12px;border-radius:10px;background:linear-gradient(180deg,#f8fffb,#eef9f3);border:1px solid rgba(31,91,69,0.04)">
            <div style="text-align:center">
              <div id="timer" style="font-size:28px;font-weight:800;color:var(--accent-2)">3:00</div>
              <div style="margin-top:10px"><button class="btn" id="startExercise">Start</button></div>
            </div>
            <div class="footnote">No audio. Visual and written cues guide the session.</div>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Tiny printable challenge area (populated by JS) -->
  <div id="printContainer" style="display:none"></div>

  <script>
    // Minimal DOM helpers
    const qs = (s)=>document.querySelector(s);
    const qsa = (s)=>document.querySelectorAll(s);

    // Exercise modal logic
    const modal = qs('#exerciseModal');
    const openBtn = qs('#openExercise');
    const closeBtn = qs('#closeExercise');
    const select = qs('#exerciseSelect');
    const content = qs('#exerciseContent');
    const timerEl = qs('#timer');
    const startBtn = qs('#startExercise');

    let timer = null; let remaining = 180;

    function formatTime(s){ const m = Math.floor(s/60); const sec = s%60; return m+':'+(sec<10?('0'+sec):sec); }

    function renderExercise(){
      const v = select.value;
      content.innerHTML = '';
      if(v==='breathing'){
        content.innerHTML = '<div style="text-align:center"><div class="breath-circle" id="breathCircle">Breathe</div><p class="footnote">Inhale 4s • hold 2s • exhale 6s. Repeat until the timer ends.</p></div>';
        remaining = 180; timerEl.textContent = formatTime(remaining);
      } else if(v==='journaling'){
        remaining = 120; timerEl.textContent = formatTime(remaining);
        content.innerHTML = '<div><strong>Prompt</strong><p style="color:var(--muted)">List three small wins from today and one step for tomorrow.</p><textarea id="journalField" rows="6" style="width:100%;padding:8px;border-radius:8px;border:1px solid rgba(16,24,32,0.06)"></textarea></div>';
      } else {
        remaining = 90; timerEl.textContent = formatTime(remaining);
        content.innerHTML = '<div><ol style="color:var(--muted)"><li>Name a core value for today.</li><li>Choose one action aligned with it.</li><li>Commit to timing or context.</li></ol></div>';
      }
    }

    openBtn.addEventListener('click', (e)=>{e.preventDefault(); modal.classList.add('open'); modal.setAttribute('aria-hidden','false'); renderExercise();});
    closeBtn.addEventListener('click', ()=>{modal.classList.remove('open'); modal.setAttribute('aria-hidden','true'); stopTimer();});
    select.addEventListener('change', renderExercise);

    function stopTimer(){ if(timer){ clearInterval(timer); timer=null; } }

    startBtn.addEventListener('click', ()=>{
      if(timer) { stopTimer(); startBtn.textContent = 'Start'; return; }
      startBtn.textContent = 'Pause';
      const mode = select.value;
      timer = setInterval(()=>{
        if(remaining<=0){ stopTimer(); timerEl.textContent = '0:00'; startBtn.textContent = 'Start'; return; }
        remaining--; timerEl.textContent = formatTime(remaining);
        if(mode==='breathing'){
          const circle = qs('#breathCircle');
          // Simple inhale/exhale cycle based on second modulo
          const cycle = remaining % 12; // 12s cycle
          if(cycle>6) circle.style.transform = 'scale(1.12)';
          else circle.style.transform = 'scale(0.92)';
        }
      },1000);
    });

    // Habit builder (compact -> full printable)
    const habitInput = qs('#habitInput');
    const makeChallenge = qs('#makeChallenge');
    const printContainer = qs('#printContainer');

    function buildPrintable(title, items){
      const days = ['Day 1','Day 2','Day 3','Day 4','Day 5','Day 6','Day 7'];
      let html = '<div style="font-family:system-ui;color:#123;padding:18px">';
      html += '<h2 style="margin:0 0 6px">7-day checklist</h2>';
      html += '<div style="color:var(--muted);margin-bottom:10px">'+(title||'Daily practice')+'</div>';
      html += '<table style="width:100%;border-collapse:collapse">';
      html += '<thead><tr><th style="text-align:left;padding:8px;border-bottom:1px solid #eee">Action</th>';
      days.forEach(d=>{ html += '<th style="padding:8px;border-bottom:1px solid #eee;text-align:center">'+d+'</th>'});
      html += '</tr></thead><tbody>';
      items.forEach(it=>{
        html += '<tr><td style="padding:10px;border-bottom:1px solid #fafafa">'+it+'</td>';
        for(let i=0;i<7;i++){ html += '<td style="padding:10px;border-bottom:1px solid #fafafa;text-align:center">☐</td>' }
        html += '</tr>';
      })
      html += '</tbody></table>';
      html += '<div style="margin-top:12px;color:var(--muted);font-size:13px">Generated by {{BUSINESS_NAME}} — use for habit tracking.</div>';
      html += '</div>';
      return html;
    }

    makeChallenge.addEventListener('click', ()=>{
      const v = (habitInput.value||'Daily micro habit').trim();
      const lines = v.split('\n').map(s=>s.trim()).filter(Boolean);
      const items = lines.length?lines:[v];
      printContainer.innerHTML = buildPrintable(v, items);
      const w = window.open('','_blank','width=700,height=800');
      if(w){
        w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Checklist</title></head><body>'+printContainer.innerHTML+'<script>window.onload=function(){window.print();};<'+'/script></body></html>');
        w.document.close();
      } else {
        alert('Popup blocked. Please allow popups or copy the text below.');
      }
    });
  </script>
</body>
</html>"} 
