<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings • {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfcfb;--muted:#56666a;--accent:#1f6b53;--card:#fff}
    body{margin:0;font-family:system-ui,Segoe UI,Roboto,Arial;color:#0b241f;background:var(--bg)}
    header{padding:18px 20px;border-bottom:1px solid rgba(0,0,0,0.04)}
    nav{max-width:1100px;margin:0 auto;display:flex;gap:18px}
    nav a{color:var(--accent);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:0 20px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(16,24,24,0.04)}
    h1{margin:0 0 8px}
    .list{display:flex;flex-direction:column;gap:12px;margin-top:12px}
    .service{padding:12px;border-radius:10px;border:1px solid rgba(16,24,24,0.04);background:linear-gradient(180deg,#fff,#f9fffb)}
    .service h4{margin:0}
    .price{font-weight:800;color:var(--accent);margin-top:6px}
    .small{font-size:13px;color:var(--muted)}
