  </style>
</head>
<body>
  <header>
    <nav class="wrap">
      <a href="index.html">Start</a>
      <a href="about.html">Approach</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Courses</a>
      <a href="pricing.html">Pricing</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>
  <div class="wrap grid">
    <div>
      <div class="card">
        <h1>Offerings: methods & formats</h1>
        <p class="small">Membership-centered support, short workshops, and modular courses designed to teach repeatable practices with measurable outcomes.</p>

        <div class="list">
          <div class="service">
            <h4>Foundations Loop — Ongoing</h4>
            <div class="small">A membership pathway focused on one weekly action, peer check-ins, and a concise review template. Ideal for steady integration into routines.</div>
            <div class="price">From $18/month</div>
            <div class="try"><a class="btn" href="pricing.html">Join the loop</a> <a class="btn alt" href="#" id="tryExercise1">Try a 2-minute reset</a></div>
          </div>

          <div class="service">
            <h4>Daily Anchor — Guided 4‑week course</h4>
            <div class="small">Four practical modules with short daily micro-tasks. Emphasis on implementing anchors into existing habits and scripted weekly reviews.</div>
            <div class="price">One-time $129 (or 3 x $45)</div>
            <div class="try"><a class="btn" href="programs.html">View schedule</a> <a class="btn alt" href="#" id="tryExercise2">Try a quick journal prompt</a></div>
          </div>

          <div class="service">
            <h4>Sustained Track — Coaching series</h4>
            <div class="small">A flexible multi-month structure for ongoing habit architecture, check-ins, and small adjustments. Best for people who want steady, measurable changes.</div>
            <div class="price">Custom pricing</div>
            <div class="try"><a class="btn" href="book.html">Start with a consult</a></div>
          </div>
        </div>

      </div>

      <div style="margin-top:14px" class="card">
        <h3>Practical features</h3>
        <ul style="color:var(--muted)">
          <li>Printable 7-day checklists you can generate and print instantly.</li>
          <li>Micro-exercises for breathing, journaling, and intention-setting.</li>
          <li>Simple weekly review templates to keep adaptations factual and short.</li>
        </ul>
      </div>
    </div>

    <aside>
      <div class="card">
        <h4>Try a short practice now</h4>
        <p class="small">Select a quick exercise and follow the on-screen prompts.</p>
        <div style="display:flex;gap:10px;margin-top:12px">
          <button class="btn" id="openExerciseSide">Try now</button>
          <a class="btn alt" href="programs.html">See course outlines</a>
        </div>
        <div style="margin-top:12px;color:var(--muted);font-size:13px">Questions? Email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>

      <div style="margin-top:12px" class="card">
        <h4>Quick habit build</h4>
        <div style="margin-top:10px">
          <input id="svcHabit" type="text" placeholder="e.g., Evening prep (5m)" style="width:100%;padding:8px;border-radius:8px;border:1px solid rgba(16,24,24,0.04)">
          <button class="btn" id="svcMake">Create checklist</button>
        </div>
      </div>
    </aside>
  </div>

  <div class="pattern" aria-hidden></div>

  <!-- Reuse a single modal for guided exercises -->
  <div id="exerciseModal2" class="modal" aria-hidden="true" style="display:none;align-items:center;justify-content:center;position:fixed;inset:0;background:rgba(6,12,10,0.44);z-index:60">
    <div style="background:#fff;padding:18px;border-radius:12px;width:520px;max-width:96%;box-shadow:0 20px 50px rgba(8,18,14,0.24)">
      <button id="close2" style="float:right;border:0;background:transparent;font-size:18px">✕</button>
      <h3 id="exTitle">Practice</h3>
      <div id="exBody" style="margin-top:10px;color:var(--muted)"></div>
      <div style="margin-top:14px;text-align:center"><button id="exStart" class="btn">Start</button></div>
    </div>
  </div>

  <script>
    // Small utilities
    const openSide = document.getElementById('openExerciseSide');
    const modal2 = document.getElementById('exerciseModal2');
    const close2 = document.getElementById('close2');
    const exTitle = document.getElementById('exTitle');
    const exBody = document.getElementById('exBody');
    const exStart = document.getElementById('exStart');

    function showModal2(title, body, duration){
      exTitle.textContent = title; exBody.innerHTML = body + '<p style="font-size:13px;color:#6b7b78">Duration: '+(duration||2)+' minutes</p>';
      modal2.style.display = 'flex'; modal2.setAttribute('aria-hidden','false');
      exStart.onclick = ()=>{ runCountdown(duration||2); }
    }

    function hideModal2(){ modal2.style.display='none'; modal2.setAttribute('aria-hidden','true'); }
    close2.addEventListener('click', hideModal2);
    openSide.addEventListener('click', ()=>{ showModal2('Breathing reset','Follow slow inhales and longer exhales. Inhale 4s, hold 2s, exhale 6s.',3); });

    // Buttons inside services list
    document.getElementById('tryExercise1').addEventListener('click', (e)=>{ e.preventDefault(); showModal2('2-minute reset','Visual and breath cues to reduce reactivity. Sit comfortably, soften your gaze.',2); });
    document.getElementById('tryExercise2').addEventListener('click', (e)=>{ e.preventDefault(); showModal2('Journal prompt','Write two sentences: what worked today and one adjustment for tomorrow.',2); });

    // Simple countdown (no complex timer UI here)
    let cd = null;
    function runCountdown(mins){ if(cd) clearInterval(cd); let t = mins*60; exStart.disabled=true; exStart.textContent='Running'; cd=setInterval(()=>{ t--; if(t<=0){ clearInterval(cd); exStart.disabled=false; exStart.textContent='Start'; alert('Session complete'); hideModal2(); } },1000); }

    // Service habit create
    document.getElementById('svcMake').addEventListener('click', ()=>{
      const v = document.getElementById('svcHabit').value.trim()||'Micro habit';
      const rows = encodeURIComponent('<html><body>'+ '<h2>'+v+'</h2>'+'<p>Seven-box checklist</p>'+'</body></html>');
      const w = window.open('about:blank');
      if(w){ w.document.write('<!doctype html><html><head><meta charset="utf-8"><title>Checklist</title></head><body><h2>'+v+'</h2><table border="1" cellpadding="8"><tr><th>Action</th><th>Days 1-7</th></tr><tr><td>'+v+'</td><td>☐ ☐ ☐ ☐ ☐ ☐ ☐</td></tr></table><script>window.onload=function(){window.print();};<'+'/script></body></html>'); w.document.close(); }
    });
  </script>
</body>
</html>"} 
