  <script>
    // Printable builder similar to other pages but self-contained
    document.getElementById('progMake').addEventListener('click', ()=>{
      const raw = document.getElementById('progHabit').value.trim() || 'Daily micro habit';
      const items = raw.split('\n').map(s=>s.trim()).filter(Boolean);
      const title = items.join(', ');
      let content = '<div style="font-family:system-ui">';
      content += '<h2>7-day checklist</h2>';
      content += '<p style="color:#556">'+(title||'Micro habit')+'</p>';
      content += '<table style="width:100%;border-collapse:collapse"><thead><tr><th style="text-align:left;border-bottom:1px solid #eee;padding:8px">Action</th>';
      for(let d=1;d<=7;d++) content += '<th style="padding:8px;border-bottom:1px solid #eee">D'+d+'</th>';
      content += '</tr></thead><tbody>';
      items.forEach(it=>{
        content += '<tr><td style="padding:8px;border-bottom:1px solid #f3f3f3">'+it+'</td>';
        for(let i=0;i<7;i++) content += '<td style="padding:8px;border-bottom:1px solid #f3f3f3;text-align:center">☐</td>';
        content += '</tr>';
      })
      if(items.length===0){ content += '<tr><td style="padding:8px;border-bottom:1px solid #f3f3f3">'+raw+'</td>'; for(let i=0;i<7;i++) content += '<td style="padding:8px;border-bottom:1px solid #f3f3f3;text-align:center">☐</td>'; content += '</tr>' }
