    });

    // Simple breathing try now (small inline modalless interaction)
    document.getElementById('tryNow').addEventListener('click', ()=>{
      const step = confirm('Begin a short 90-second breathing reset?\n\nInhale 4s • hold 2s • exhale 6s. Press OK to begin.');
      if(!step) return;
      let t=90; const iv = setInterval(()=>{ t--; if(t<=0){ clearInterval(iv); alert('Complete — notice any change in steadiness.'); } },1000);
    });
  </script>
